INSERT INTO page_schemas (id, page_key, page_url, schema_name, schema_type, schema_description, schema_json, status, created_at, updated_at) VALUES ('1', 'home', '/', 'Primary Enterprise Organization Schema', 'Organization', '<p>Primary corporate identity schema establishing BusinessDoctor as an enterprise IT, cloud, and digital transformation consultancy firm.</p>', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"Organization\",\n    \"@id\": \"{{BASE_URL}}/#organization\",\n    \"name\": \"BusinessDoctor\",\n    \"legalName\": \"BusinessDoctor IT Solutions & Digital Services Private Limited\",\n    \"url\": \"{{BASE_URL}}/\",\n    \"logo\": \"{{BASE_URL}}/assets/img/logo.svg\",\n    \"description\": \"BusinessDoctor is an enterprise digital transformation, cloud architecture, and full-stack software development consulting firm.\",\n    \"telephone\": \"+1 (800) 492-3628\",\n    \"email\": \"solutions@businessdoctor.com\",\n    \"address\": {\n        \"@type\": \"PostalAddress\",\n        \"streetAddress\": \"Sector 62, Innovation Corridor\",\n        \"addressLocality\": \"Noida\",\n        \"addressRegion\": \"UP\",\n        \"postalCode\": \"201301\",\n        \"addressCountry\": \"IN\"\n    },\n    \"sameAs\": [\n        \"https://www.linkedin.com/company/businessdoctor\",\n        \"https://twitter.com/businessdoctor\",\n        \"https://github.com/businessdoctor\"\n    ]\n}', 'active', '2026-11-06 08:46:59', '2026-11-06 08:46:59');
INSERT INTO page_schemas (id, page_key, page_url, schema_name, schema_type, schema_description, schema_json, status, created_at, updated_at) VALUES ('2', 'home', '/', 'Website Global Authority Schema', 'WebSite', '<p>Declares the website root entity and enables Google Sitelinks query integration.</p>', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"WebSite\",\n    \"@id\": \"{{BASE_URL}}/#website\",\n    \"url\": \"{{BASE_URL}}/\",\n    \"name\": \"BusinessDoctor\",\n    \"description\": \"Enterprise IT solutions, high-growth digital strategy, and full-stack engineering consultancy.\",\n    \"publisher\": {\n        \"@id\": \"{{BASE_URL}}/#organization\"\n    },\n    \"potentialAction\": {\n        \"@type\": \"SearchAction\",\n        \"target\": {\n            \"@type\": \"EntryPoint\",\n            \"urlTemplate\": \"{{BASE_URL}}/insights.php?q={search_term_string}\"\n        },\n        \"query-input\": \"required name=search_term_string\"\n    }\n}', 'active', '2026-11-06 08:46:59', '2026-11-06 08:46:59');
INSERT INTO page_schemas (id, page_key, page_url, schema_name, schema_type, schema_description, schema_json, status, created_at, updated_at) VALUES ('3', 'about', '/about.php', 'About Us Corporate Purpose Schema', 'AboutPage', '<p>Signals to Google knowledge graph about BusinessDoctor leadership, mission, and technical philosophy.</p>', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"AboutPage\",\n    \"@id\": \"{{BASE_URL}}/about.php#aboutpage\",\n    \"url\": \"{{BASE_URL}}/about.php\",\n    \"name\": \"About BusinessDoctor \\u2014 Enterprise IT & Growth Consultancy\",\n    \"description\": \"Learn about BusinessDoctor executive leadership, engineering principles, and our multidisciplinary IT practice.\",\n    \"mainEntity\": {\n        \"@id\": \"{{BASE_URL}}/#organization\"\n    }\n}', 'active', '2026-11-06 08:46:59', '2026-11-06 08:46:59');
INSERT INTO page_schemas (id, page_key, page_url, schema_name, schema_type, schema_description, schema_json, status, created_at, updated_at) VALUES ('4', 'services', '/services.php', 'IT Services Portfolio & OfferCatalog', 'ProfessionalService', '<p>Defines the four core engineering practices: Web Development, Performance Marketing, UI/UX, and Cloud Solutions.</p>', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"ProfessionalService\",\n    \"@id\": \"{{BASE_URL}}/services.php#professionalservice\",\n    \"name\": \"BusinessDoctor IT Services\",\n    \"url\": \"{{BASE_URL}}/services.php\",\n    \"priceRange\": \"$$$\",\n    \"hasOfferCatalog\": {\n        \"@type\": \"OfferCatalog\",\n        \"name\": \"Enterprise IT & Digital Services Portfolio\",\n        \"itemListElement\": [\n            {\n                \"@type\": \"Offer\",\n                \"itemOffered\": {\n                    \"@type\": \"Service\",\n                    \"name\": \"Web & Custom Software Engineering\",\n                    \"description\": \"Architecting resilient full-stack web applications, microservices, and enterprise APIs.\"\n                }\n            },\n            {\n                \"@type\": \"Offer\",\n                \"itemOffered\": {\n                    \"@type\": \"Service\",\n                    \"name\": \"Digital Marketing & Performance SEO\",\n                    \"description\": \"Data-driven growth engines, revenue attribution, and organic search dominance.\"\n                }\n            },\n            {\n                \"@type\": \"Offer\",\n                \"itemOffered\": {\n                    \"@type\": \"Service\",\n                    \"name\": \"UI/UX Design & Brand Identity Systems\",\n                    \"description\": \"Human-centered user experience design, interactive design tokens, and design systems.\"\n                }\n            },\n            {\n                \"@type\": \"Offer\",\n                \"itemOffered\": {\n                    \"@type\": \"Service\",\n                    \"name\": \"Cloud Solutions & DevOps Automation\",\n                    \"description\": \"Cloud-native infrastructure, Kubernetes orchestration, and continuous delivery pipelines.\"\n                }\n            }\n        ]\n    }\n}', 'active', '2026-11-06 08:46:59', '2026-11-06 08:46:59');
INSERT INTO page_schemas (id, page_key, page_url, schema_name, schema_type, schema_description, schema_json, status, created_at, updated_at) VALUES ('5', 'service-detail', '/services/{slug}', 'Dynamic Practice Area Service Schema', 'Service', '<p>Dynamically populates based on active practice area URL parameter.</p>', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"Service\",\n    \"name\": \"{{PAGE_TITLE}}\",\n    \"url\": \"{{CANONICAL_URL}}\",\n    \"description\": \"{{PAGE_DESCRIPTION}}\",\n    \"provider\": {\n        \"@id\": \"{{BASE_URL}}/#organization\"\n    },\n    \"areaServed\": \"Global\",\n    \"serviceType\": \"Enterprise Consulting\"\n}', 'active', '2026-11-06 08:46:59', '2026-11-06 08:46:59');
INSERT INTO page_schemas (id, page_key, page_url, schema_name, schema_type, schema_description, schema_json, status, created_at, updated_at) VALUES ('6', 'diagnostic', '/diagnostic.php', 'Digital Architecture Diagnostic Audit Tool', 'WebPage', '<p>Marks up the interactive digital health and architecture diagnostic assessment.</p>', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"WebPage\",\n    \"name\": \"Enterprise Digital Diagnostic & IT Health Audit\",\n    \"url\": \"{{BASE_URL}}/diagnostic.php\",\n    \"description\": \"Benchmark your technology stack, operational bottlenecks, and digital maturity in minutes.\",\n    \"publisher\": {\n        \"@id\": \"{{BASE_URL}}/#organization\"\n    }\n}', 'active', '2026-11-06 08:46:59', '2026-11-06 08:46:59');
INSERT INTO page_schemas (id, page_key, page_url, schema_name, schema_type, schema_description, schema_json, status, created_at, updated_at) VALUES ('7', 'case-studies', '/case-studies.php', 'Client Case Studies & Proven Results Collection', 'WebPage', '<p>Portfolio listing of verified enterprise transformations and quantified business outcomes.</p>', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"WebPage\",\n    \"name\": \"Client Case Studies & Transformations \\u2014 BusinessDoctor\",\n    \"url\": \"{{BASE_URL}}/case-studies.php\",\n    \"description\": \"Explore proven case studies demonstrating measurable growth and software transformation across industries.\",\n    \"publisher\": {\n        \"@id\": \"{{BASE_URL}}/#organization\"\n    }\n}', 'active', '2026-11-06 08:46:59', '2026-11-06 08:46:59');
INSERT INTO page_schemas (id, page_key, page_url, schema_name, schema_type, schema_description, schema_json, status, created_at, updated_at) VALUES ('8', 'case-study-detail', '/case-study-detail.php', 'Dynamic Client Case Study Article Schema', 'Article', '<p>Dynamically pulls client industry, challenge, outcome, and canonical slug for rich snippets.</p>', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"Article\",\n    \"headline\": \"{{ARTICLE_TITLE}}\",\n    \"url\": \"{{CANONICAL_URL}}\",\n    \"description\": \"{{ARTICLE_DESCRIPTION}}\",\n    \"publisher\": {\n        \"@id\": \"{{BASE_URL}}/#organization\"\n    },\n    \"author\": {\n        \"@type\": \"Organization\",\n        \"name\": \"BusinessDoctor\"\n    }\n}', 'active', '2026-11-06 08:46:59', '2026-11-06 08:46:59');
INSERT INTO page_schemas (id, page_key, page_url, schema_name, schema_type, schema_description, schema_json, status, created_at, updated_at) VALUES ('9', 'insights', '/insights.php', 'Perspectives & Engineering Insights Blog', 'WebPage', '<p>Main editorial collection page for technical perspectives, architecture guides, and strategic commentary.</p>', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"WebPage\",\n    \"name\": \"Perspectives & Technical Insights \\u2014 BusinessDoctor\",\n    \"url\": \"{{BASE_URL}}/insights.php\",\n    \"description\": \"Technical blueprints, cloud architecture strategies, and leadership insights from BusinessDoctor experts.\",\n    \"publisher\": {\n        \"@id\": \"{{BASE_URL}}/#organization\"\n    }\n}', 'active', '2026-11-06 08:46:59', '2026-11-06 08:46:59');
INSERT INTO page_schemas (id, page_key, page_url, schema_name, schema_type, schema_description, schema_json, status, created_at, updated_at) VALUES ('10', 'insight-detail', '/insight-detail.php', 'Dynamic Technical Article & BlogPosting Schema', 'BlogPosting', '<p>Rich Google-compatible BlogPosting schema with dynamic headline, author, datePublished, image, and canonical URL.</p>', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"BlogPosting\",\n    \"mainEntityOfPage\": {\n        \"@type\": \"WebPage\",\n        \"@id\": \"{{CANONICAL_URL}}\"\n    },\n    \"headline\": \"{{ARTICLE_TITLE}}\",\n    \"description\": \"{{ARTICLE_DESCRIPTION}}\",\n    \"image\": \"{{FEATURED_IMAGE}}\",\n    \"datePublished\": \"{{DATE_PUBLISHED}}\",\n    \"dateModified\": \"{{DATE_MODIFIED}}\",\n    \"author\": {\n        \"@type\": \"Person\",\n        \"name\": \"{{AUTHOR_NAME}}\"\n    },\n    \"publisher\": {\n        \"@id\": \"{{BASE_URL}}/#organization\"\n    }\n}', 'active', '2026-11-06 08:46:59', '2026-11-06 08:46:59');
INSERT INTO page_schemas (id, page_key, page_url, schema_name, schema_type, schema_description, schema_json, status, created_at, updated_at) VALUES ('11', 'contact', '/contact.php', 'Contact Us & Advisory Inquiries Schema', 'ContactPage', '<p>Marks up the primary contact point and advisory consultation inquiry channels.</p>', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"ContactPage\",\n    \"@id\": \"{{BASE_URL}}/contact.php#contactpage\",\n    \"url\": \"{{BASE_URL}}/contact.php\",\n    \"name\": \"Contact BusinessDoctor \\u2014 Enterprise Advisory & Consultation\",\n    \"description\": \"Initiate a dialogue with BusinessDoctor solution architects and digital practice directors.\",\n    \"mainEntity\": {\n        \"@type\": \"ContactPoint\",\n        \"telephone\": \"+1 (800) 492-3628\",\n        \"contactType\": \"customer service\",\n        \"email\": \"solutions@businessdoctor.com\",\n        \"availableLanguage\": [\n            \"English\",\n            \"Hindi\"\n        ]\n    }\n}', 'active', '2026-11-06 08:46:59', '2026-11-06 08:46:59');
